package com.primehr.security;import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;
@Component public class EvidenceFrameworkPermissionGuard{public static final String FRAMEWORK="primehr.evidence-framework";private final AdministrativeAuthorizationClient client;public EvidenceFrameworkPermissionGuard(AdministrativeAuthorizationClient client){this.client=client;}public void require(PrimeHrAction action,String token){var p=client.resolve(FRAMEWORK,token);boolean allowed=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case PUBLISH->p.canPublish();case ARCHIVE->p.canDelete();default->false;};if(!allowed||!p.administrator()&&p.dataScope()!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Evidence framework administration requires agency-wide permission");}}
